import { describe, expect, test } from 'vitest';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, resolve } from 'node:path';
import { parseFrontmatter } from '@astrojs/markdown-remark';

/**
 * The "Built with NaN" badge: SVGs in public/badge, generated by
 * scripts/gen-badges.mjs, and the /docs/built-with-nan page with the snippets
 * people paste into their READMEs.
 *
 * Owner's ask (2026-10-15, community thread): something like Gentle-AI's
 * "Built with Gentle-AI", with a URL we can search GitHub for to find the
 * projects that carry it. Designs B (card, dark and light) and C (compact)
 * were picked from the proposals.
 *
 * The badge URLs are a contract: other people's READMEs point at them, so a
 * renamed file breaks every badge out there without any error on our side.
 */
const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../../..');
const badgeDir = resolve(root, 'public/badge');
const read = (p: string) => readFileSync(p, 'utf-8');

const BADGES = ['built-with-nan-dark.svg', 'built-with-nan-light.svg', 'built-with-nan-compact.svg'];

const pages = {
  en: { file: 'src/content/docs/built-with-nan.mdx', group: 'Guides' },
  es: { file: 'src/content/docs-es/built-with-nan.mdx', group: 'Guías' },
} as const;

const body = (raw: string) => raw.replace(/^---[\s\S]*?\n---\n/, '');
const codeBlocks = (b: string) => [...b.matchAll(/```[\s\S]*?```/g)].map((m) => m[0]);

describe('the badge files', () => {
  test('are exactly the published set', () => {
    expect(readdirSync(badgeDir).sort()).toEqual([...BADGES].sort());
  });

  /**
   * Hand-editing a committed SVG would be undone by the next run of the
   * script, so the two must agree.
   */
  test('match what scripts/gen-badges.mjs generates', async () => {
    const { renderBadges } = await import(pathToFileURL(resolve(root, 'scripts/gen-badges.mjs')).href);
    const generated = renderBadges() as Record<string, string>;
    expect(Object.keys(generated).sort()).toEqual([...BADGES].sort());
    for (const name of BADGES) expect(read(resolve(badgeDir, name)), name).toBe(generated[name]);
  });

  /**
   * GitHub renders README images inside an <img>, where an SVG cannot load
   * fonts or anything else from outside. Text has to be paths, or the badge
   * shows in whatever fallback font the reader's browser picks.
   */
  test.each(BADGES)('%s is self-contained', (name) => {
    const svg = read(resolve(badgeDir, name));
    expect(svg).not.toMatch(/<text\b|<image\b|<foreignObject\b|<style\b|font-family|@import|href=|url\(\s*['"]?(https?:|\/\/)/i);
    expect(svg).toContain('role="img"');
    expect(svg).toContain('<title>Built with NaN</title>');
    expect(svg.length).toBeLessThan(16 * 1024);
  });
});

describe.each(Object.entries(pages))('the %s page', (_lang, page) => {
  const raw = read(resolve(root, page.file));
  const fm = parseFrontmatter(raw).frontmatter as Record<string, unknown>;
  const snippets = codeBlocks(body(raw)).join('\n');

  test('sits in the guides group', () => {
    expect(fm.group).toBe(page.group);
    expect(fm.title).toBe('Built with NaN');
  });

  test('offers the card with both themes and the compact badge', () => {
    expect(snippets).toContain('srcset="https://nan.builders/badge/built-with-nan-light.svg"');
    expect(snippets).toContain('src="https://nan.builders/badge/built-with-nan-dark.svg"');
    expect(snippets).toContain('(https://nan.builders/badge/built-with-nan-compact.svg)');
  });

  test('only points at badge files that exist', () => {
    const urls = [...raw.matchAll(/(?:https:\/\/nan\.builders)?\/badge\/([\w.-]+)/g)].map((m) => m[1]);
    expect(urls.length).toBeGreaterThan(0);
    for (const f of urls) expect(existsSync(resolve(badgeDir, f)), f).toBe(true);
  });

  /** The ref is how a click from a README shows up in our analytics. */
  test('links every snippet back with the ref', () => {
    const links = [...snippets.matchAll(/(?:href="|\]\()(https:\/\/nan\.builders\/[^")]*)/g)]
      .map((m) => m[1])
      .filter((u) => !u.includes('/badge/'));
    expect(links.length).toBe(2);
    for (const l of links) expect(l).toBe('https://nan.builders/?ref=built-with-nan');
  });
});

test('both languages publish the same snippets', () => {
  const [en, es] = [pages.en, pages.es].map((p) => codeBlocks(body(read(resolve(root, p.file)))));
  expect(es).toEqual(en);
});
